    // Медіакіт (public/advertise.php)
    'adv_title' => ['Реклама на AI LAB HUB', 'Advertise on AI LAB HUB'],
    'adv_meta' => ['Відеореклама в каталозі AI-інструментів AI LAB HUB: формати, вимоги до креативу, ціни, аудиторія за реальною аналітикою й правила.', 'Video ads in the AI LAB HUB directory of AI tools: formats, creative specs, prices, audience from real analytics and rules.'],
    'adv_intro' => ['AI LAB HUB — каталог AI-інструментів українською та англійською з блогом і асистенткою Елею. Відвідувачі приходять, щоб знайти інструмент під конкретне завдання, тож коротке відео про ваш продукт поруч із тематичним контентом бачать люди, яким ця тема цікава.', 'AI LAB HUB is a directory of AI tools in Ukrainian and English, with a blog and the assistant Elya. Visitors come to find a tool for a specific task, so a short video about your product next to topical content is seen by people interested in that topic.'],
    'adv_benefit_1' => ['Тематичне розміщення: оберіть категорії й підкатегорії, поруч із якими показувати рекламу.', 'Topical placement: choose the categories and subcategories next to which your ad is shown.'],
    'adv_benefit_2' => ['Оплата лише за результат обраної моделі: за покази (CPM) або за кліки (CPC), з балансу, без абонплати.', 'You pay only for your chosen model: impressions (CPM) or clicks (CPC), from a prepaid balance, no subscription.'],
    'adv_benefit_3' => ['Власний денний і загальний бюджет, пауза чи завершення кампанії будь-коли.', 'Your own daily and total budget; pause or end a campaign at any time.'],
    'adv_benefit_4' => ['Статистика показів, переглядів і кліків у кабінеті з вивантаженням у CSV.', 'Impression, view and click statistics in your account, with CSV export.'],
    'adv_benefit_5' => ['Без стеження за відвідувачами: таргетинг лише за мовою, пристроєм і темою сторінки.', 'No visitor tracking: targeting only by language, device and page topic.'],
    'adv_no_guarantee' => ['Ми не обіцяємо конкретної кількості показів, кліків чи продажів — прогноз у кабінеті орієнтовний.', 'We do not promise any number of impressions, clicks or sales — the forecast in the account is approximate.'],
    'adv_how_title' => ['Як це працює', 'How it works'],
    'adv_step_1' => ['Реєстрація', 'Sign up'],
    'adv_step_1_text' => ['Створіть акаунт або увійдіть — розділ «Реклама» з’явиться в кабінеті.', 'Create an account or log in — the “Advertising” section appears in your account.'],
    'adv_step_2' => ['Створення кампанії', 'Create a campaign'],
    'adv_step_2_text' => ['Майстер із 5 кроків: ціль, відео й тексти, аудиторія, бюджет, підтвердження.', 'A 5-step wizard: objective, video and texts, audience, budget, confirmation.'],
    'adv_step_3' => ['Модерація й оплата', 'Review and payment'],
