    'adv_cta' => ['Створити кампанію', 'Create a campaign'],
    'adv_cta_closed' => ['Прийом рекламних кампаній зараз закритий. Напишіть нам — повідомимо, коли відкриємо.', 'We are not accepting ad campaigns right now. Write to us and we will let you know when we open.'],
    'adv_formats_title' => ['Формати й розміщення', 'Formats and placements'],
    'adv_formats_note' => ['Усі формати — одна картка відео з позначкою «Реклама», заголовком, описом і кнопкою. Нижче — справжній компонент сайту з демонстраційним постером.', 'Every format is the same video card labelled “Sponsored”, with a title, description and button. Below is the real site component with a demo poster.'],
    'adv_place_catalog_card' => ['Картка в каталозі й пошуку: третьою позицією в сітці продуктів категорії, підкатегорії або результатів пошуку. Одна рекламна картка на сторінку.', 'Directory and search card: third position in the product grid of a category, subcategory or search results. One ad card per page.'],
    'adv_place_product_page' => ['Сторінка продукту: під описом інструмента, перед списком функцій.', 'Product page: below the tool description, before the feature list.'],
