    'adv_demo_poster' => ['Ваше відео 16:9', 'Your 16:9 video'],
    'adv_spec_title' => ['Технічні вимоги до креативу', 'Creative specifications'],
    'adv_spec_video' => ['Відео: файл MP4 (H.264) або WebM, до %s МБ і до %s с; або посилання на YouTube.', 'Video: an MP4 (H.264) or WebM file, up to %s MB and up to %s s; or a YouTube link.'],
    'adv_spec_ratio' => ['Співвідношення сторін 16:9 (наприклад, 1280×720 або 1920×1080). Відео стартує без звуку — головне має бути зрозуміло без звуку.', 'Aspect ratio 16:9 (e.g. 1280×720 or 1920×1080). Videos start muted — the key message must work without sound.'],
    'adv_spec_title_len' => ['Заголовок: до 60 символів.', 'Title: up to 60 characters.'],
