    'adv_spec_poster' => ['Постер (обкладинка): JPG, PNG або WebP до 2 МБ, 16:9; можна взяти кадр із відео в майстрі.', 'Poster (cover): JPG, PNG or WebP up to 2 MB, 16:9; you can capture a frame from the video in the wizard.'],
    'adv_spec_url' => ['Адреса переходу: лише https://, сторінка має відкриватися без помилок і належати тому, що рекламується.', 'Destination URL: https:// only; the page must open without errors and belong to what is advertised.'],
    'adv_spec_cta' => ['Кнопка: «Детальніше», «Спробувати», «Перейти» або «Завантажити».', 'Button: “Learn more”, “Try it”, “Go” or “Download”.'],
    'adv_good_title' => ['Правильно', 'Do'],
    'adv_good_1' => ['Чіткий кадр продукту в перші 2–3 секунди й текст, що читається на телефоні.', 'A clear shot of the product in the first 2–3 seconds and text readable on a phone.'],
    'adv_good_2' => ['Заголовок описує, що це й для кого: «Транскрипція зустрічей українською».', 'A title that says what it is and for whom: “Meeting transcription in Ukrainian”.'],
    'adv_good_3' => ['Посилання веде на сторінку того самого продукту з тієї самої адреси.', 'The link leads to the page of the same product at the same domain.'],
    'adv_bad_title' => ['Неправильно', 'Don’t'],
    'adv_bad_1' => ['Обіцянки гарантованого результату чи прибутку, «чудодійні» ефекти.', 'Promises of guaranteed results or profit, “miracle” effects.'],
    'adv_bad_2' => ['Скорочені посилання (bit.ly тощо) і переадресації на інший домен.', 'Shortened links (bit.ly etc.) and redirects to another domain.'],
    'adv_bad_3' => ['Імітація інтерфейсу сайту, системних повідомлень чи кнопок, яких немає.', 'Imitating the site interface, system messages or non-existent buttons.'],
    'adv_prices_title' => ['Ціни', 'Prices'],
    'adv_prices_note' => ['Ціни в доларах США. Ціна фіксується в кампанії в момент надсилання на модерацію. Оплата — з балансу в доларах; поповнення переказом у гривнях за курсом НБУ на день оплати.', 'Prices are in US dollars. The price is fixed in the campaign when it is submitted for review. Payment comes from your balance in dollars; top-ups are paid in hryvnias at the National Bank of Ukraine rate on the day of payment.'],
    'adv_prices_on_request' => ['Ціни за запитом — напишіть на %s.', 'Prices on request — write to %s.'],
